    snagRetreat: 1.4,
    dropAheadF: 0.10,             // dropped thread lands this far ahead (path fraction)
    dropSpacingF: 0.07,
    recoveryLoopTime: 2.6,        // local loop that returns Purl to the landing entry
    failDelay: 1.2,

    ribbonUnfurl: 1.3,
